-- ---- public.invitations
alter table public."invitations" enable row level security;
revoke all on table public."invitations" from anon, authenticated;
grant DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE on table public."invitations" to anon;
grant DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE on table public."invitations" to authenticated;
do $r$ declare p record; begin
  for p in select policyname from pg_policies where schemaname='public' and tablename='invitations' loop
    execute format('drop policy %I on public.%I', p.policyname, 'invitations');
  end loop; end $r$;
create policy "Org admins create invitations" on public."invitations" as permissive for insert to public with check ((org_id IN ( SELECT organization_members.organization_id
   FROM organization_members
  WHERE ((organization_members.user_id = auth.uid()) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'org_admin'::text, 'super_admin'::text]))))));
create policy "Org admins delete invitations" on public."invitations" as permissive for delete to public using ((org_id IN ( SELECT organization_members.organization_id
   FROM organization_members
  WHERE ((organization_members.user_id = auth.uid()) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'org_admin'::text, 'super_admin'::text]))))));
create policy "Org admins view invitations" on public."invitations" as permissive for select to public using ((org_id IN ( SELECT organization_members.organization_id
   FROM organization_members
  WHERE ((organization_members.user_id = auth.uid()) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'org_admin'::text, 'super_admin'::text]))))));
create policy "Public can update invitation by token" on public."invitations" as permissive for update to public using (true);
create policy "Public can view invitations" on public."invitations" as permissive for select to public using (true);
create policy "Users can update own invitations" on public."invitations" as permissive for update to "authenticated" using ((email = ( SELECT (auth.jwt() ->> 'email'::text))));
alter table public.invitations alter column invited_by drop default;
-- ---- public.add_user_to_organization(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.add_user_to_organization(p_user_id uuid, p_org_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
  v_name text;
begin
  if exists (select 1 from public.organization_members
             where organization_id = p_org_id and user_id = p_user_id) then
    return;
  end if;

  select au.email, coalesce(au.raw_user_meta_data->>'full_name', au.email)
    into v_email, v_name
  from auth.users au where au.id = p_user_id;

  if v_email is null then
    raise exception 'add_user_to_organization: user % not found', p_user_id;
  end if;

  insert into public.organization_members
    (organization_id, user_id, full_name, email, role, status, joined_at,
     created_at, updated_at)
  values (p_org_id, p_user_id, v_name, v_email, coalesce(p_role, 'member'),
          'active', now(), now(), now())
  on conflict (organization_id, email)
  do update set user_id = excluded.user_id,
                role = excluded.role,
                status = 'active',
                joined_at = coalesce(public.organization_members.joined_at, now()),
                updated_at = now();
end;
$function$;
revoke execute on function public.add_user_to_organization(uuid,uuid,text) from public, anon, authenticated;
grant execute on function public.add_user_to_organization(uuid,uuid,text) to service_role;
-- ---- public.enable_hse_for_organization(uuid)
CREATE OR REPLACE FUNCTION public.enable_hse_for_organization(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_role text;
begin
  select om.organization_id, om.role into v_org_id, v_role
  from public.organization_members om
  where om.user_id = p_user_id
    and coalesce(lower(om.status), 'active') = 'active'
  limit 1;

  if v_org_id is null then
    raise exception 'User does not belong to an organization';
  end if;

  if v_role not in ('owner', 'admin', 'org_admin', 'super_admin') then
    raise exception 'Only organization admins can enable HSE';
  end if;

  -- Previous body updated organizations.hse_enabled / subscribed_modules /
  -- modules — columns renamed *_legacy in the organizations renovation, so it
  -- has been erroring at runtime. Modern provisioning mirrors
  -- handle_new_user: hse_status flag + organization_apps + purchased_modules.
  update public.organizations set hse_status = 'ACTIVE' where id = v_org_id;

  insert into public.organization_apps
    (organization_id, app_id, module_id, seats_allocated, seats_used, status, created_at)
  select v_org_id, 'hse', 'hse_free', 999, 0, 'ACTIVE', now()
  where not exists (
    select 1 from public.organization_apps
    where organization_id = v_org_id and app_id = 'hse' and module_id = 'hse_free');

  insert into public.purchased_modules
    (organization_id, module_id, module_name, status, subscription_status,
     purchase_date, seats_allocated, auto_renew)
  select v_org_id, 'hse_free', 'HSE Free Tier', 'active', 'active', now(), 999, false
  where not exists (
    select 1 from public.purchased_modules
    where organization_id = v_org_id and module_id = 'hse_free');

  update public.users
  set subscribed_modules = (
        select array_agg(distinct x)
        from unnest(array_append(coalesce(subscribed_modules, array[]::text[]), 'hse_free')) t(x))
  where organization_id = v_org_id;

  insert into public.app_activity_log (user_id, app_name, action, timestamp)
  values (p_user_id, 'suite', 'enable_hse_free', now());
end;
$function$;
revoke execute on function public.enable_hse_for_organization(uuid) from public, anon, authenticated;
grant execute on function public.enable_hse_for_organization(uuid) to service_role;
-- ---- public.handle_new_user(): back to the 01 TRANSITIONAL body (token or legacy path), so the
-- HSE page and Suite function shipped after 01 keep working. Copied from the 01 migration file.
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  org_id UUID;
  org_name TEXT;
  meta_full_name TEXT;
  meta_primary_app TEXT;
  meta_org_text TEXT;
  meta_invitation_token TEXT;
  v_joined JSONB;
  v_legacy_role TEXT;  -- TRANSITIONAL (01 only; 02 removes)
BEGIN
  BEGIN
    RAISE LOG 'handle_new_user: Starting for user %', NEW.id;

    -- Read metadata, with sensible defaults for any missing keys
    meta_org_text         := NULLIF(BTRIM(NEW.raw_user_meta_data->>'organization_id'), '');
    meta_invitation_token := NULLIF(BTRIM(NEW.raw_user_meta_data->>'invitation_token'), '');
    org_name         := COALESCE(NEW.raw_user_meta_data->>'organization_name', NEW.email);
    meta_full_name   := COALESCE(NEW.raw_user_meta_data->>'full_name', 'New User');
    meta_primary_app := COALESCE(NEW.raw_user_meta_data->>'primary_app', 'suite');

    -- Defensive: clamp primary_app to known values
    IF meta_primary_app NOT IN ('suite', 'hse') THEN
      meta_primary_app := 'suite';
    END IF;

    -- ------------------------------------------------------------------------
    -- 1a0. Invitation signup: the token (not the metadata) decides the org
    --      and the role. Raises if the token, email or inviter is not valid.
    -- ------------------------------------------------------------------------
    IF meta_invitation_token IS NOT NULL THEN
      v_joined := public.invitation_accept_internal(
                    meta_invitation_token, NEW.id, NEW.email,
                    NEW.raw_user_meta_data->>'full_name');
      org_id := (v_joined->>'organization_id')::UUID;
      IF meta_org_text IS NOT NULL AND meta_org_text::UUID IS DISTINCT FROM org_id THEN
        RAISE EXCEPTION 'invitation is for a different organization';
      END IF;
    ELSIF meta_org_text IS NOT NULL THEN
      -- TRANSITIONAL (01 only): the pre-2026-10 signup path, unchanged, so the
      -- live HSE page and the old accept-employee-invitation keep working until
      -- they are replaced. 02 turns this branch into a refusal.
      org_id := meta_org_text::UUID;
      v_legacy_role := COALESCE(NEW.raw_user_meta_data->>'role', 'owner');
    END IF;

    -- ------------------------------------------------------------------------
    -- 1a. If signup flow (no invitation), create the org
    -- ------------------------------------------------------------------------
    IF org_id IS NULL THEN
      RAISE LOG 'handle_new_user: Creating new organization for user %', NEW.id;

      INSERT INTO public.organizations (
        name,
        contact_email,
        created_by,
        created_via,
        organization_type,
        subscription_tier,
        subscription_status,
        hse_status,
        suite_status,
        setup_completed,
        created_at
      )
      VALUES (
        org_name,
        NEW.email,
        NEW.id,
        'signup',
        'customer',
        'free',
        'active',
        'ACTIVE',                                         -- HSE is free for everyone
        CASE WHEN meta_primary_app = 'suite' THEN 'TRIAL' ELSE 'NONE' END,
        FALSE,                                            -- setup wizard not yet run
        NOW()
      )
      RETURNING id INTO org_id;
    END IF;

    -- ------------------------------------------------------------------------
    -- 1b. Upsert public.users
    -- ------------------------------------------------------------------------
    INSERT INTO public.users (
        id,
        email,
        organization_id,
        primary_app,
        subscribed_modules,
        last_accessed_app,
        app_preferences,
        created_at,
        updated_at
    )
    VALUES (
        NEW.id,
        NEW.email,
        org_id,
        meta_primary_app,
        ARRAY['hse_free']::text[],
        meta_primary_app,
        jsonb_build_object(
          meta_primary_app,
          jsonb_build_object(
            'onboarding_completed', FALSE,
            'preferred_language',   'en',
            'notifications_enabled', TRUE
          )
        ),
        NOW(),
        NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
        organization_id = EXCLUDED.organization_id,
        primary_app     = EXCLUDED.primary_app,
        updated_at      = NOW();

    IF v_joined IS NULL THEN
    -- ------------------------------------------------------------------------
    -- 1c. The creator of a new organization joins it as its owner.
    --     (An invitee's membership was written by invitation_accept_internal.)
    -- ------------------------------------------------------------------------
    INSERT INTO public.organization_members (
        organization_id,
        user_id,
        full_name,
        email,
        role,
        status,
        joined_at,
        created_at,
        updated_at
    )
    VALUES (
        org_id,
        NEW.id,
        meta_full_name,
        NEW.email,
        COALESCE(v_legacy_role, 'owner'),                  -- creator; legacy join (01 only) keeps its metadata role
        'active',                                          -- creator joins active, not invited
        NOW(),
        NOW(),
        NOW()
    )
    ON CONFLICT (organization_id, email) DO UPDATE SET
        user_id    = EXCLUDED.user_id,
        full_name  = COALESCE(public.organization_members.full_name, EXCLUDED.full_name),
        status     = 'active',
        joined_at  = COALESCE(public.organization_members.joined_at, NOW()),
        updated_at = NOW();

    -- ------------------------------------------------------------------------
    -- 1c2. Provision app access (NEW table: organization_apps)
    --      Free HSE for every new org. Suite signups also get suite app
    --      provisioned in TRIAL state — actual entitlement gated downstream
    --      by purchased_modules and the org's suite_status.
    -- ------------------------------------------------------------------------
    INSERT INTO public.organization_apps (
        organization_id,
        app_id,
        module_id,
        seats_allocated,
        seats_used,
        status,
        created_at
    )
    VALUES (
        org_id,
        'hse',
        'hse_free',
        999,                                               -- unlimited for free tier
        0,
        'ACTIVE',
        NOW()
    )
    ON CONFLICT (organization_id, app_id) DO NOTHING;

    IF meta_primary_app = 'suite' THEN
      INSERT INTO public.organization_apps (
          organization_id,
          app_id,
          module_id,
          seats_allocated,
          seats_used,
          status,
          created_at
      )
      VALUES (
          org_id,
          'suite',
          'suite_trial',
          5,                                               -- nominal trial seat allocation
          0,
          'ACTIVE',
          NOW()
      )
      ON CONFLICT (organization_id, app_id) DO NOTHING;
    END IF;

    -- ------------------------------------------------------------------------
    -- 1d. Free HSE entitlement record in purchased_modules
    -- ------------------------------------------------------------------------
    INSERT INTO public.purchased_modules (
        organization_id,
        module_id,
        module_name,
        status,
        subscription_status,
        purchase_date,
        seats_allocated,
        auto_renew
    )
    SELECT
        org_id,
        'hse_free',
        'HSE Free Tier',
        'active',
        'active',
        NOW(),
        999,
        FALSE
    WHERE NOT EXISTS (
        SELECT 1 FROM public.purchased_modules
        WHERE organization_id = org_id AND module_id = 'hse_free'
    );
    END IF;

    -- ------------------------------------------------------------------------
    -- 1e. user_points_summary
    -- ------------------------------------------------------------------------
    INSERT INTO public.user_points_summary (
        user_id,
        organization_id,
        total_points,
        points_earned,
        points_redeemed,
        created_at,
        updated_at
    )
    VALUES (
        NEW.id,
        org_id,
        0,
        0,
        0,
        NOW(),
        NOW()
    )
    ON CONFLICT (user_id) DO UPDATE SET
        organization_id = EXCLUDED.organization_id,
        updated_at      = NOW();

    -- ------------------------------------------------------------------------
    -- 1f. user_profiles
    -- ------------------------------------------------------------------------
    INSERT INTO public.user_profiles (
        id,
        org_id,
        full_name,
        updated_at
    )
    VALUES (
        NEW.id,
        org_id,
        meta_full_name,
        NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
        org_id    = COALESCE(EXCLUDED.org_id, public.user_profiles.org_id),
        full_name = COALESCE(EXCLUDED.full_name, public.user_profiles.full_name);

    RAISE LOG 'handle_new_user: Successfully completed for user % (org %)', NEW.id, org_id;

  EXCEPTION WHEN OTHERS THEN
    RAISE LOG 'handle_new_user: ERROR for user % - %', NEW.id, SQLERRM;
    RAISE EXCEPTION 'Failed to initialize user: %', SQLERRM;
  END;

  RETURN NEW;
END;
$function$;
